import Foundation
import Testing
@testable import STPDCore   // exercises the internal maxFactorCount / rankDropColumns / sortLoadings helpers

// NM-3D: R-compatible Neural Manifold Factor Analysis (and GPFA-style smoothed variant) on `matrix.scaled`.
// Reference loadings / uniquenesses / scores are generated by R 4.6.0 `stats::factanal(X, factors = 3,
// scores = "regression", rotation = "none", control = list(nstart = 20))` for the deterministic 40×6 input
// below. Comparison is up to per-factor sign (classical FA sign ambiguity, fixed by factanal's sortLoadings).

private func matrix(scaled: [[Double]]) -> NeuralPopulationMatrix {
    let nBins = scaled.count
    let nNeurons = scaled.first?.count ?? 0
    var bins: [NeuralPopulationBin] = []
    for i in 0..<nBins {
        let start = Double(i)
        bins.append(NeuralPopulationBin(binID: i + 1, startSec: start, endSec: start + 1,
                                        midSec: start + 0.5, widthSec: 1))
    }
    let ids = (0..<nNeurons).map { "n\($0)" }
    return NeuralPopulationMatrix(
        bins: bins, trainIDs: ids, trainNames: ids,
        counts: scaled, rates: scaled, signal: scaled, scaled: scaled,
        transform: .sqrtCount, scaling: .zscore, timeOrigin: .raw,
        binSec: 1, smoothingSigmaBins: 0, windowStartSec: 0, windowEndSec: Double(nBins)
    )
}

