/// R `fit$loadings` (6 × 3, after `sortLoadings`).
private let referenceLoadings: [[Double]] = [
    [0.8445616658, -0.5304094318, 0.0195583534],
    [0.8297790982, 0.0030197295, -0.0202652847],
