    [0.0032119737, 0.8400576474, 0.2794283296],
    [-0.3114958171, 0.6976738659, 0.4679350100],
]
private let referenceUniqueness: [Double] = [
    0.0050000000, 0.3110468321, 0.0050000000, 0.1839211976, 0.2162126296, 0.1972583772,
]
private let referenceMeanUniqueness = 0.1530731728
/// R `fit$scores` rows 1–6 and 39–40 (n = 40).
private let referenceScoresHead: [[Double]] = [
    [0.6992840491, -0.3299570862, -0.3602616539],
    [0.6751341009, -0.7621372282, -0.7017739446],
    [0.5071883568, -1.1583638943, -1.0897886107],
    [0.2196157819, -1.4608104566, -1.3140493211],
    [-0.1490327961, -1.6240681695, -1.2331650803],
    [-0.5503527883, -1.6231142602, -0.8374703765],
]
private let referenceScoresTail: [[Double]] = [
    [1.6167873952, -1.0732127260, 1.4693620033],
    [1.3849296198, -1.4340666273, 2.0078720181],
]

/// The sign `s ∈ {+1,−1}` aligning a Swift factor column to its R reference (FA sign ambiguity).
private func columnSign(_ swift: [Double], _ ref: [Double]) -> Double {
    let plus = zip(swift, ref).map { abs($0 - $1) }.max() ?? 0
    let minus = zip(swift, ref).map { abs($0 + $1) }.max() ?? 0
    return plus <= minus ? 1 : -1
}

// MARK: - R parity

@Test
func neuralFactorMatchesRReferenceUpToSign() throws {
    let result = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: referenceMatrix), maxFactors: 3)
    #expect(result.diagnostics.factorCount == 3)
    #expect(result.loadings.count == 6)
    #expect(result.points.count == 40)

    // Loadings, per factor, up to sign; remember the sign to apply to the scores.
    var factorSign = [1.0, 1.0, 1.0]
    for c in 0..<3 {
        let swiftColumn = result.loadings.map { [$0.f1 ?? .nan, $0.f2 ?? .nan, $0.f3 ?? .nan][c] }
        let refColumn = referenceLoadings.map { $0[c] }
        let sign = columnSign(swiftColumn, refColumn)
        factorSign[c] = sign
        let maxDiff = zip(swiftColumn, refColumn).map { abs($0 - sign * $1) }.max() ?? 0
        #expect(maxDiff < 2e-3, "loadings factor \(c + 1) max diff \(maxDiff)")
    }

    // Uniquenesses (sign-independent).
    let swiftUniqueness = result.loadings.map { $0.uniqueness }
    let uniqDiff = zip(swiftUniqueness, referenceUniqueness).map { abs($0 - $1) }.max() ?? 0
    #expect(uniqDiff < 2e-3, "uniqueness max diff \(uniqDiff)")
    #expect(abs(result.diagnostics.meanUniqueness - referenceMeanUniqueness) < 2e-3)
    // Heywood boundary preserved (R clamps uniqueness at 0.005).
    #expect(swiftUniqueness.allSatisfy { $0 >= 0.005 - 1e-9 })

    // Scores (head rows 0–5, tail rows 38–39), each factor with the SAME sign as its loadings column.
    func checkScores(_ swiftRows: [[Double]], _ refRows: [[Double]]) {
        for (swiftRow, refRow) in zip(swiftRows, refRows) {
            for c in 0..<3 {
                #expect(abs(swiftRow[c] - factorSign[c] * refRow[c]) < 5e-3,
                        "score factor \(c + 1) diff \(abs(swiftRow[c] - factorSign[c] * refRow[c]))")
            }
        }
    }
    let head = result.points.prefix(6).map { [$0.nm1, $0.nm2, $0.nm3] }
    let tail = result.points.suffix(2).map { [$0.nm1, $0.nm2, $0.nm3] }
    checkScores(Array(head), referenceScoresHead)
    checkScores(Array(tail), referenceScoresTail)
}

// MARK: - Shape / no sampling

@Test
func neuralFactorEmbedsEveryBinNoSampling() throws {
    // 50 bins (far above any sampled-method cap); FA must embed all of them 1:1 in order — there is no
    // `maxPoints` parameter on `run`.
    let rows = referenceMatrix + referenceMatrix.prefix(10)   // 50 × 6, still well-conditioned
    let result = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: rows), maxFactors: 3)
    #expect(result.points.count == 50)
    #expect(result.points.map { $0.bin.binID } == Array(1...50))
    #expect(result.diagnostics.inputBinCount == 50)
}

@Test
func neuralFactorIsDeterministic() throws {
    let a = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: referenceMatrix))
    let b = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: referenceMatrix))
    #expect(a.points == b.points)
    #expect(a.loadings == b.loadings)
}

@Test
func neuralFactorDiagnosticsAndLabels() throws {
    let fa = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: referenceMatrix))
    #expect(fa.diagnostics.methodLabel == "FA")
    #expect(fa.diagnostics.smoothed == false)
    #expect(fa.diagnostics.keptFeatureCount == 6)
    #expect(fa.diagnostics.droppedFeatureCount == 0)
    #expect(fa.loadings.allSatisfy { $0.f1 != nil && $0.f2 != nil && $0.f3 != nil })
}

// MARK: - GPFA-style (smoothed)

@Test
func neuralFactorGPFASmoothingChangesEmbeddingAndLabel() throws {
    let fa = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: referenceMatrix), smoothingSigmaBins: nil)
    let gpfa = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: referenceMatrix), smoothingSigmaBins: 2)
    #expect(gpfa.diagnostics.smoothed == true)
    #expect(gpfa.diagnostics.methodLabel == "GPFA-style smooth FA")
    let differs = zip(fa.points, gpfa.points).contains { abs($0.nm1 - $1.nm1) > 1e-6 || abs($0.nm2 - $1.nm2) > 1e-6 }
    #expect(differs, "Gaussian smoothing should change the GPFA-style embedding")
}

// MARK: - Factor-count rule (mirror of stpd_state_trajectory_max_fa_factors)

@Test
func neuralFactorMaxFactorCountMatchesR() {
    #expect(NeuralPopulationFactorAnalysis.maxFactorCount(featureCount: 2, maxFactors: 3) == 0)
    #expect(NeuralPopulationFactorAnalysis.maxFactorCount(featureCount: 3, maxFactors: 3) == 1)
    #expect(NeuralPopulationFactorAnalysis.maxFactorCount(featureCount: 4, maxFactors: 3) == 1)
    #expect(NeuralPopulationFactorAnalysis.maxFactorCount(featureCount: 5, maxFactors: 3) == 2)
    #expect(NeuralPopulationFactorAnalysis.maxFactorCount(featureCount: 6, maxFactors: 3) == 3)
    #expect(NeuralPopulationFactorAnalysis.maxFactorCount(featureCount: 10, maxFactors: 3) == 3)
}

// MARK: - Guards

@Test
func neuralFactorRejectsTooFewBins() {
    let small = Array(referenceMatrix.prefix(2))   // 2 < 3
    #expect(throws: NeuralPopulationFactorError.tooFewBins) {
        _ = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: small))
    }
}

@Test
func neuralFactorRejectsTooFewFeatures() {
    let twoColumns = referenceMatrix.map { Array($0.prefix(2)) }   // 40 × 2 → p < 3
    #expect(throws: NeuralPopulationFactorError.tooFewFeatures) {
        _ = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: twoColumns))
    }
}

@Test
func neuralFactorRejectsNotIdentified() {
    // 3 bins × 3 independent columns → factorCount 1 but nrow 3 < 1 + 3.
    let tiny: [[Double]] = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    #expect(throws: NeuralPopulationFactorError.notIdentified) {
        _ = try NeuralPopulationFactorAnalysis.run(matrix: matrix(scaled: tiny))
    }
}
